import math

def smallest_exponent_in_factorial(n, p):
    """ Calculate the smallest exponent of a prime p that divides n! """
    exponents = 0
    power = p
    while power <= n:
        exponents += n // power
        power *= p
    return exponents

def calculate_f(n):
